static inline int m44b_skip_draw(unsigned long long verts)
{
    unsigned long long n;
    if (!m44b_nodraw()) return 0;
    n = atomic_fetch_add_explicit(&g_m44b_nodraw_n, 1ull, memory_order_relaxed);
    if ((n % 512ull) == 0) vk_boot_logf("[m44b] nodraw suppressed n=%llu verts_total=%llu", n + 1ull, verts);
    return 1;
}
#define vkCmdDraw(_cb, _vc, _ic, _fv, _fi) \
    (m44b_skip_draw((unsigned long long)(_vc) * ((_ic) ? (unsigned long long)(_ic) : 1ull)) ? (void)0 : \
     (m40x_hit(6, 0), m40al_draw_hit((unsigned long long)(_vc) * ((_ic) ? (unsigned long long)(_ic) : 1ull)), vkCmdDraw(_cb, _vc, _ic, _fv, _fi)))
#define vkCmdDrawIndexed(_cb, _ic, _ins, _fi, _vo, _fins) \
    (m44b_skip_draw((unsigned long long)(_ic) * ((_ins) ? (unsigned long long)(_ins) : 1ull)) ? (void)0 : \
     (m40x_hit(7, 0), m40al_draw_hit((unsigned long long)(_ic) * ((_ins) ? (unsigned long long)(_ins) : 1ull)), vkCmdDrawIndexed(_cb, _ic, _ins, _fi, _vo, _fins)))
#define vkCmdBindIndexBuffer(_cb, _bf, _off, _ty) \
    (m40x_hit(8, 0), vkCmdBindIndexBuffer(_cb, _bf, _off, _ty))

/* ================= M40AO（2026-11-10）：每帧那批「固定非-draw 工作」按 Vulkan 调用类别归属 =================
   反常事实（M40AN 两次 boot）：draw_wait_us 在 draw_n=375 与 18093 两种配置下都≈40–49 s/60 s 窗，
   与 draw 数（差 48×）、submit 数（差 3.9×）都无关；而同窗 [m40ah] CPU 284–342%、
   Thread<00..03>（SwiftShader 的 4 条 marl worker）88–93% ⇒ 每帧烧的是一批「固定非-draw 工作」。
   本探针只做旁路计数（宏体一律 (计数, 原调用)），不改任何提交/等待/渲染/合并逻辑：
     rp     = vkCmdBeginRenderPass 次数（本文件 6 处调用点全在本段之后 ⇒ 全被宏覆盖；下同）
     rp0    = 其中「一笔 draw 都没录」的通道数：begin 时快照 g_m40al_draws，end 时差值仍 0 即记一次
     px     = Σ renderArea.extent.w*h（poll 里折成 px_mp = 百万像素）
     clear  = vkCmdClearColorImage / vkCmdClearDepthStencilImage / vkCmdClearAttachments 次数
     copy   = vkCmdCopyImage / vkCmdCopyBufferToImage / vkCmdCopyImageToBuffer / vkCmdBlitImage 次数
     bar    = vkCmdPipelineBarrier 次数
     jit    = 心跳线程读一次 /proc/self/maps，数含 .smo_jit 的行（SwiftShader JIT 段；不改渲染线程）
   rp0 的快照栈是 __thread（录制线程各一份，深度 >16 只丢样本、不改配对判定），多线程录制互不踩。
   关态（smo_m40ao=0）零输出；计数器照常累加（宏不判开关，热路径只多一次原子加，与 m40am/m40al 同口径）。 */
