/* ================= M40AI：建管线耗时记账 + 串行化实验 =================
   M40AH 已证：冻结期 3–4 线程各 ~80% CPU 烧在 SwiftShader JIT，且崩点在 .smo_jit_* 匿名代码页。
   要判的是「并发 JIT 竞态」还是「可执行内存耗尽」⇒ 给唯一建管线入口 m40ac_create_pipe() 加计时，
   并可用 smo_m40ai_lock=1 把该入口整体串行（同一时刻只允许一个 JIT）。
   非 static：跨文件读（nvn_vk_m40ai_poll 在本文件，写入点也只有本文件；定义在此供 dumpsym 可见）。 */
_Atomic unsigned long long g_m40ai_n, g_m40ai_us, g_m40ai_max_us;
extern int smo_m40ai_lock(void);   /* 定义在 gfx_bridge.c（B 优先+A 兜底，默认 0） */
extern int m40ai_on(void);         /* 定义在 gfx_bridge.c（[m40ai] 探针开关，默认 0） */

/* ================= M40AJ：冻结期 CPU 归因（建图 / 上传 / 建管线 / 剩余） =================
   M40AI 已证：冻结窗口进程 CPU≈348%（3.5 核），而唯一建管线入口 m40ac_create_pipe() 累计只占
   ~0.27 核（t=202 窗 dms=5.4 s / 20 s）⇒ **冻结的大头不在建管线**。本组计数器把冻结期拆成四份：
     img_ms = 建图（nvn_vk_tex_create：vkCreateImage/vkAllocateMemory/vkCreateImageView + CPU 布局）
     up_ms  = 纹理上传（nvn_vk_tex_upload_storage：deswizzle/BC 判据 + vkCmdCopyBufferToImage 提交）
     cp_ms  = 建管线（直接复用 g_m40ai_n/g_m40ai_us，m40ac_create_pipe 早已记账，不重复埋点）
     rest_ms= 窗口墙钟 − 上面三者 = 引擎线程（JIT 主循环 / 命令重放 / 解析 / 其它）
   记账本身 = 两次 clock_gettime + 两次原子加，不进任何判据；[m40aj] 探针关态零输出。
   非 static：跨文件同步读（nvn_vk_m40aj_poll 在本文件，写入点也只有本文件；定义在此供 dumpsym 可见）。 */
_Atomic unsigned long long g_m40aj_img_n, g_m40aj_img_us, g_m40aj_up_n, g_m40aj_up_us, g_m40aj_up_bytes;
extern int m40aj_on(void);   /* 定义在 gfx_bridge.c（[m40aj] 探针开关，默认 0） */

/* ================= M6t A1：阻塞的宿主等待必须把虚拟核交出去 =================
   M6s 坐实：渲染线程 0x1004（mask=core1）在 draw_flush 的 240 s 栅栏里一直占着 core1，于是
   `[core] busy=[1.8% 99.1% 1.1%]`，而 h=0x1023/h=0x102c 每 30 s 窗口累计 29 s 的换核等待。
   threads.c 的 block() 早已在 CV/锁/地址等待上 core_put→core_take，真正漏掉的是**绕过 block 的宿主
   长等待**：vkWaitForFences 的每一次调用。这里统一收口：栅栏等待前交出虚拟核，返回后重新申请。
   非客体线程（心跳/语音等）调用时 runtime_core_away() 返回 0，什么也不做；套嵌套时只有最外层生效。
   开关 TOTK_CORE_AWAY=0 可关（默认开），便于做「改前/改后」对照。 */
static int core_away_on(void)
{
    static int on = -1;
    if (on < 0) { const char *e = getenv("TOTK_CORE_AWAY"); on = e ? (atoi(e) != 0) : 1; }
    return on;
}
int runtime_core_away(void); void runtime_core_back(int *away);   /* threads.c */
static VkResult nvk_wait_fences(VkDevice d, uint32_t nf, const VkFence *f, VkBool32 all, uint64_t to)
{
    int away = 0;
    if (core_away_on()) away = runtime_core_away();
    /* M40AL：只夹计时，不改 core_away 语义与返回路径（时间戳都在 core_back 之前取，量到的是纯栅栏等待）。 */
    struct timespec m40al_a, m40al_b; clock_gettime(CLOCK_MONOTONIC, &m40al_a);
    VkResult r = vkWaitForFences(d, nf, f, all, to);
    clock_gettime(CLOCK_MONOTONIC, &m40al_b);
    if (away) runtime_core_back(&away);
    m40al_wait_add(m40al_a, m40al_b);   /* M40AL：wait_n/wait_us 累计（同一对计数器，与排空共用） */
    return r;
}

/* M6e 段 2 优化开关。口径同 smo_heavy_skip：env -> 沙箱文件 -> 应用默认值。
   SELinux 下 hdc 不能新建文件，所以**默认值必须在 C 里**（缺省 = 开 = 采用优化）。 */
static int pf_opt_off(const char *envn, const char *fa, const char *fb)
{
    const char *e = getenv(envn);
    if (e && *e) return atoi(e) == 0;
    const char *p[2] = { fa, fb };
    for (int i = 0; i < 2; i++) {
        FILE *f = fopen(p[i], "r");
        if (!f) continue;
        char b[32] = {0};
        if (fgets(b, sizeof b, f)) { fclose(f); return atoi(b) == 0; }
        fclose(f);
    }
    return 0;                       /* 缺省：开 */
}
#define PF_FA(x) "/data/storage/el2/base/files/" x
#define PF_FB(x) "/data/app/el2/100/base/com.vibecc.smo/files/" x
/* ① RT 绑定 CB 的栅栏等待改成「提交即返回、延迟回收」（队列 FIFO 保证顺序；只有真要读回时才必须等）。 */
static int pf_opt_rt_async(void)
{
    static int v = -1;
    if (v < 0) v = !pf_opt_off("SMO_PERF_RT_ASYNC", PF_FA("smo_perf_rt_async"), PF_FB("smo_perf_rt_async"));
    return v;
}

